def _features(q: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
    q = q - q[..., :1]
    s = q.abs().amax(-1, keepdim=True).clamp_min(1e-30)
    return q / s, torch.log(s[..., 0])

